-- Package price by engine class: 150-250cc uses the id+250 row, 251-500cc the id+500 row. If the 500 row is missing, the 250 price plus the old surcharge is used; if a tier row is missing, the standard price.
create or replace function public.crm_booking_price(p_service text, p_addons text[], p_engine text) returns integer language plpgsql stable security definer set search_path = public as $$
declare tot int; a text; t250 int; t500 int; fee int;
begin
  select price into tot from public.services where id = p_service and kind = 'service' and active;
  if tot is null then raise exception 'choose a valid service' using errcode = 'P0001'; end if;
  if p_service in ('basic', 'general', 'full') and p_engine in ('mid', 'big') then
    select price into t250 from public.services where id = p_service || '250' and kind = 'service' and active;
    select price into t500 from public.services where id = p_service || '500' and kind = 'service' and active;
    if p_engine = 'mid' then tot := coalesce(t250, tot);
    elsif t500 is not null then tot := t500;
    else
      tot := coalesce(t250, tot);
      select price into fee from public.services where id = 'bigbike' and kind = 'fee' and active; tot := tot + coalesce(fee, 300);
    end if;
  end if;
  foreach a in array coalesce(p_addons, '{}') loop
    if not exists (select 1 from public.services where id = a and kind = 'addon' and active) then raise exception 'unknown add-on: %', left(a, 20) using errcode = 'P0001'; end if;
    tot := tot + (select price from public.services where id = a);
  end loop;
  return tot;
end; $$;
revoke all on function public.crm_booking_price(text, text[], text) from public;

-- Desk catalog: the engine-class rows are prices of a package, not separate services.
create or replace function public.crm_booking_catalog() returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.crm_need_role();
  if not (public.crm_can('create_bookings') or public.crm_can('edit_leads')) then raise exception 'you do not have permission to do this' using errcode = '42501'; end if;
  return jsonb_build_object(
    'services', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'price', price, 'description', description) order by sort, id) from public.services where kind = 'service' and active and id !~ '(250|500)$'), '[]'::jsonb),
    'addons', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'price', price) order by sort, id) from public.services where kind = 'addon' and active), '[]'::jsonb),
    'tiers', jsonb_build_object(
      'mid', coalesce((select jsonb_object_agg(replace(id, '250', ''), price) from public.services where kind = 'service' and active and id in ('basic250', 'general250', 'full250')), '{}'::jsonb),
      'big', coalesce((select jsonb_object_agg(replace(id, '500', ''), price) from public.services where kind = 'service' and active and id in ('basic500', 'general500', 'full500')), '{}'::jsonb)),
    'big_fee', case when exists (select 1 from public.services where id = 'basic500' and active) then 0 else coalesce((select price from public.services where id = 'bigbike' and kind = 'fee' and active), 300) end);
end; $$;
